(()=>{
  const $=id=>document.getElementById(id),cal=$('calendarGrid');if(!cal)return;
  const arrival=$('arrival'),departure=$('departure'),inArrival=$('inquiryArrival'),inDeparture=$('inquiryDeparture'),guests=$('guests'),monthTitle=$('calendarMonth'),prev=$('calendarPrev'),next=$('calendarNext'),estimate=$('rentalEstimate'),form=$('retreatForm'),quote=$('retreatQuote');
  const today=new Date();today.setHours(12,0,0,0);let viewed=new Date(today.getFullYear(),today.getMonth(),1,12),start='',end='';
  const stamp=date=>date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');
  const fromStamp=s=>s?new Date(s+'T12:00:00'):null;
  const daysBetween=(a,b)=>Math.round((fromStamp(b)-fromStamp(a))/86400000);
  const mockOccupied=d=>[8,9,17,25].includes(d.getDate())||((d.getDate()===13||d.getDate()===14)&&d.getMonth()%2===0);
  const isOccupied=s=>mockOccupied(fromStamp(s));
  const blockedBetween=(a,b)=>{const d=fromStamp(a),last=fromStamp(b);for(d.setDate(d.getDate()+1);d<last;d.setDate(d.getDate()+1))if(mockOccupied(d))return true;return false};
  const min=stamp(today);[arrival,departure,inArrival,inDeparture].forEach(el=>el.min=min);
  const showEstimate=(message)=>{if(message){estimate.textContent=message;return}if(!start||!end){estimate.textContent=start?'Arrival selected. Choose a departure at least two nights later.':'Select two dates to preview your sample stay.';return}const nights=daysBetween(start,end),total=nights*195;estimate.textContent=nights+' nights · $195 per night · $'+total.toLocaleString('en-US')+' illustrative subtotal. No booking will be made.'};
  const sync=()=>{arrival.value=start;departure.value=end;inArrival.value=start;inDeparture.value=end;const earliest=start?fromStamp(start):today;earliest.setDate(earliest.getDate()+2);const minEnd=stamp(earliest);departure.min=minEnd;inDeparture.min=minEnd;showEstimate();render()};
  const choose=s=>{if(!start||end||s<=start){start=s;end=''}else if(daysBetween(start,s)<2){showEstimate('Please choose a departure at least two nights after arrival.');return}else if(blockedBetween(start,s)){showEstimate('Those dates include a sample occupied night. Choose another range.');return}else end=s;sync()};
  function render(){monthTitle.textContent=viewed.toLocaleDateString('en-US',{month:'long',year:'numeric'}).toUpperCase();cal.replaceChildren();['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach(name=>{const el=document.createElement('span');el.className='weekday';el.textContent=name;cal.append(el)});const y=viewed.getFullYear(),m=viewed.getMonth(),first=new Date(y,m,1,12),last=new Date(y,m+1,0,12);for(let i=0;i<first.getDay();i++){const e=document.createElement('span');e.className='empty';cal.append(e)}for(let d=1;d<=last.getDate();d++){const date=new Date(y,m,d,12),s=stamp(date),occupied=mockOccupied(date),past=date<today,button=document.createElement('button');button.type='button';button.textContent=d;button.setAttribute('aria-label',date.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})+(occupied?', sample occupied':'')+(past?', past date':''));if(occupied)button.classList.add('occupied');if(s===min)button.classList.add('today');if(s===start||s===end)button.classList.add('selected-date');else if(start&&end&&s>start&&s<end)button.classList.add('in-range');button.disabled=past||occupied;button.addEventListener('click',()=>choose(s));cal.append(button)}prev.disabled=viewed.getFullYear()===today.getFullYear()&&viewed.getMonth()===today.getMonth()};
  prev.addEventListener('click',()=>{viewed=new Date(viewed.getFullYear(),viewed.getMonth()-1,1,12);render()});next.addEventListener('click',()=>{viewed=new Date(viewed.getFullYear(),viewed.getMonth()+1,1,12);render()});
  const handleDates=()=>{const a=arrival.value,b=departure.value;if(a&&a<min){showEstimate('Please choose a future arrival.');return}if(a&&isOccupied(a)){showEstimate('That sample arrival date is shown as occupied.');return}if(b&&isOccupied(b)){showEstimate('That sample departure date is shown as occupied.');return}if(a&&b&&(daysBetween(a,b)<2||blockedBetween(a,b))){showEstimate('Choose a range of at least two nights without sample occupied dates.');return}start=a;end=b;const focus=fromStamp(start||min);viewed=new Date(focus.getFullYear(),focus.getMonth(),1,12);sync()};
  arrival.addEventListener('change',handleDates);departure.addEventListener('change',handleDates);
  inArrival.addEventListener('change',()=>{arrival.value=inArrival.value;handleDates()});inDeparture.addEventListener('change',()=>{departure.value=inDeparture.value;handleDates()});
  document.querySelectorAll('[data-rental]').forEach(b=>b.addEventListener('click',()=>{$('selectedRental').value=b.dataset.rental;$('stay').scrollIntoView({behavior:'smooth'});b.blur()}));
  form.onsubmit=e=>{e.preventDefault();const a=inArrival.value,b=inDeparture.value,name=$('guestName').value.trim(),email=$('guestEmail').value.trim(),rental=$('selectedRental').value;if(!a||!b||daysBetween(a,b)<2){quote.classList.add('visible');quote.replaceChildren();const h=document.createElement('strong');h.textContent='Please review your dates.';quote.append(h);quote.scrollIntoView({behavior:'smooth',block:'nearest'});return}if(rental==='The Stillwater Cabin'&&(isOccupied(a)||isOccupied(b)||blockedBetween(a,b))){quote.classList.add('visible');quote.replaceChildren();const h=document.createElement('strong');h.textContent='Please choose unblocked sample dates.';quote.append(h);quote.scrollIntoView({behavior:'smooth',block:'nearest'});return}const nights=daysBetween(a,b),rate=({'The Stillwater Cabin':195,'Fern Hollow':285,'Cedar Observatory':320,'Whispering Pines':225})[rental]||195;quote.classList.add('visible');quote.replaceChildren();const h=document.createElement('strong');h.textContent='Your inquiry preview is ready.';const summary=document.createElement('p');summary.textContent=name+', your fictional inquiry for '+rental+' is '+nights+' nights ('+a+' to '+b+'), from $'+(nights*rate).toLocaleString('en-US')+' before taxes or fees, for '+$('adults').value+' adult(s) and '+$('children').value+' child(ren).';const contact=document.createElement('p');contact.textContent='Contact preference: '+$('contactMethod').value+'. Email entered: '+email+'. This is an on-screen preview only; no information was transmitted, saved, or sent to an owner. There is no reservation.';const other=document.createElement('p');const extras=[...form.querySelectorAll('[name="addons"]:checked')].map(x=>x.value);other.textContent='Special requests: '+(extras.join(', ')||'None selected')+'. Preferred budget: '+$('budget').value+'. Pets: '+$('pets').value+'.';quote.append(h,summary,contact,other);quote.scrollIntoView({behavior:'smooth',block:'nearest'})};
  const photoButtons=[...document.querySelectorAll('.rental-gallery-photo')],lightbox=$('rentalLightbox'),lightImg=$('rentalLightboxImage'),caption=$('rentalPhotoCaption');let photo=0;const display=i=>{photo=(i+photoButtons.length)%photoButtons.length;const source=photoButtons[photo],img=source.querySelector('img');lightImg.src=img.src;lightImg.alt=img.alt;caption.textContent=source.querySelector('span').textContent.replace('↗','').trim()};const close=()=>{lightbox.hidden=true;document.body.style.overflow='';photoButtons[photo].focus()};photoButtons.forEach((b,i)=>b.addEventListener('click',()=>{display(i);lightbox.hidden=false;document.body.style.overflow='hidden';$('rentalLightboxClose').focus()}));$('rentalLightboxClose').addEventListener('click',close);$('rentalPhotoPrev').addEventListener('click',()=>display(photo-1));$('rentalPhotoNext').addEventListener('click',()=>display(photo+1));lightbox.addEventListener('click',e=>{if(e.target===lightbox)close()});document.addEventListener('keydown',e=>{if(lightbox.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')display(photo+1);if(e.key==='ArrowLeft')display(photo-1)});
  render();showEstimate();
})();
